# Function to recursively find all IDs
def find_ids(component, path=''):
    ids = []
    if hasattr(component, 'id'):
        ids.append(path + str(component.id))
    if hasattr(component, 'children'):
        children = component.children
        if isinstance(children, list):
            for i, child in enumerate(children):
                ids.extend(find_ids(child, f'{path}{i}.'))
        elif children is not None:
            ids.extend(find_ids(children, f'{path}children.'))
    return ids

