@app.server.route("/_api/chat", methods=["POST"])
def api_chat():
    """API endpoint to chat with the Ollama LLM.

    Expects JSON payload:
    {
        "message": "Your message to the LLM",
        "host": "ollama host" (optional, defaults to config),
        "port": 11434 (optional, defaults to config),
        "model": "llama3.2" (optional, defaults to config)
    }

    Special commands:
    - If message is "/whoami", returns agent description without calling Ollama

    Returns:
    {
        "status": "success" or "error",
        "response": "LLM response text",
        "sender": "assistant" or "agent",
        "model": "model used"
    }
    """
    from flask import request
    import json

    try:
        data = request.get_json()
        if not data:
            return {"status": "error", "message": "No JSON payload provided"}, 400

        message = data.get("message", "")
        host = data.get("host", config.llm_host)
        port = data.get("port", config.llm_port)
        model = data.get("model", config.llm_model)

        if not message or not message.strip():
            return {"status": "error", "message": "Message is required"}, 400

        # Handle /whoami command
        if message.strip().lower() == "/whoami":
            from src.callbacks.chat import whoami_tool
            return {
                "status": "success",
                "response": whoami_tool(),
                "sender": "agent",
                "model": "N/A"
            }

        # Send to Ollama
        import requests
        base_url = f"http://{host}:{port}"
        payload = {
            "model": model,
            "prompt": message,
            "stream": False,
        }

        url = f"{base_url}/api/generate"
        response = requests.post(url, json=payload, timeout=120)
        response.raise_for_status()
        result = response.json()

        raw_response = result.get("response", "")

        # Clean up markdown code fences if present
        if raw_response.startswith("```"):
            raw_response = raw_response.lstrip("```").lstrip()
        if raw_response.endswith("```"):
            raw_response = raw_response.rstrip("```").rstrip()

        return {
            "status": "success",
            "response": raw_response,
            "sender": "assistant",
            "model": model
        }

    except requests.exceptions.RequestException as e:
        logger.error(f"Chat API request failed: {e}")
        return {
            "status": "error",
            "message": f"Failed to connect to Ollama: {str(e)}",
            "model": model
        }, 500
    except json.JSONDecodeError as e:
        logger.error(f"Chat API JSON decode error: {e}")
        return {
            "status": "error",
            "message": f"Invalid JSON response from Ollama: {str(e)}",
            "model": model
        }, 500
    except Exception as e:
        logger.error(f"Chat API error: {e}", exc_info=True)
        return {
            "status": "error",
            "message": str(e),
            "model": model
        }, 500

